const NOOP = () => () => {};
/** The page's URL fragment without `#`, followed through `hashchange`: artifact kinds read a place inside the artifact from it. */
const subscribeHash = (change: () => void) => { globalThis.addEventListener?.('hashchange', change); return () => globalThis.removeEventListener?.('hashchange', change); };
const readHash = () => (globalThis.location?.hash ?? '').replace(/^#/, '');
const POLL_MS = 1500;
const EXTENSION = /\.([A-Za-z0-9]{1,8})$/;

/** One retained revision of a file with its save time (`files.saves(path)` of `@hachej/boring-files/workspace`). */
export type SavedRevision = FileRevision;

/** What a host viewer for an artifact type or file kind the block does not render itself (for example a tldraw canvas) receives. */
export interface CustomViewerProps {
  readonly target: ArtifactTarget;
  readonly title: string;
  /** A pinned revision, read-only; absent: follow the latest. */
  readonly revision?: string | undefined;
  /** Pass these on to the `ViewerFrame` around it: test ids, the version switcher or back button, Close, the share target. */
  readonly frame: Pick<ViewerFrameProps, 'testId' | 'titleTestId' | 'headerStart' | 'controls' | 'onClose' | 'target'>;
}
/** Host viewers by artifact type or file kind (`canvas`, or any other). They take precedence over the built-in ones. */
export type CustomViewers = Readonly<Record<string, (props: CustomViewerProps) => ReactNode>>;

/** Everything a viewer in the panel reads through: one resource client, the version history, host viewers and policy. */
export interface ViewerOptions {
  readonly client: ResourceClient;
  readonly identity: ResourceIdentity;
  readonly history?: ((path: string) => Promise<readonly SavedRevision[]>) | undefined;
  readonly viewers?: CustomViewers | undefined;
  /**
   * Every kind the panel and the file viewer resolve through, in order (the first match wins): its label names the artifact in the bar and
   * its `renderer` or lazily loaded `load` draws it. The panel knows no kind of its own: without this list every artifact shows as text.
   * The pi-app-kinds item's `defaultKinds()` is the default list (maquette, diagram, mock-up and records, then Markdown, HTML, SVG, CSV,
   * image and PDF); a host puts its own kinds before it, or passes a list of its own. A `viewers` entry wins over a document kind
   * (`fallback`), not over a host's kind.
   */
  readonly kinds?: readonly PanelKind[] | undefined;
  /** The host's opt-in to running HTML pages in the sandboxed preview. */
  readonly interactive?: InteractiveHtml | undefined;
  readonly share?: ViewerShare | undefined;
  readonly onUnsavedChange?: ((unsaved: boolean) => void) | undefined;
  readonly onBeforeLeaveChange?: ((flush: (() => Promise<boolean>) | null) => void) | undefined;
  /** Told each revision a built-in viewer has mounted and shows (after it loads, never before): the page's acknowledgement of `present`. */
  readonly onShown?: ((shown: { readonly path: string; readonly revision: string; readonly hidden?: true }) => void) | undefined;
  /** Told when an artifact kind could not show a revision (its `onFailed`, or its renderer threw): the page refuses a `present` of that file. */
  readonly onFailed?: ((failed: { readonly path: string; readonly revision: string; readonly reason: string }) => void) | undefined;
  /** Where the host serves blob bytes (a checked same-origin path, default `/_files/`): a pointer file opens from `<blobBase><id>`. */
  readonly blobBase?: string | undefined;
}

/** Reports `revision` of `path` once the viewer showing it has mounted (an effect, so never before the panel really shows it), and `hidden` when it stops. */
export function useReportShown(onShown: ViewerOptions['onShown'], path: string, revision: string | undefined): void {
  useEffect(() => {
    if (revision === undefined || !onShown) return undefined;
    onShown({ path, revision });
    return () => onShown({ path, revision, hidden: true });
  }, [onShown, path, revision]);
}

/** Draws a kind's renderer as its own component, so a throw is caught by `KindBoundary` and reported as a failure. */
function KindView({ render, props }: { readonly render: (props: ArtifactKindViewProps) => ReactNode; readonly props: ArtifactKindViewProps }) {
  return <>{render(props)}</>;
}

/**
 * Catches a kind renderer that throws: shows a short note instead of the view and reports the failure once. A new `revision` clears the
 * note without remounting the renderer: a stateful kind (the board's local frame, its save and conflict state) survives its own saves.
 */
class KindBoundary extends Component<{ readonly revision: string; readonly onError: () => void; readonly message: string; readonly children: ReactNode }, { readonly failed: boolean; readonly revision: string }> {
  override state = { failed: false, revision: this.props.revision };
  static getDerivedStateFromError(): { failed: boolean } { return { failed: true }; }
  static getDerivedStateFromProps(props: { readonly revision: string }, state: { readonly failed: boolean; readonly revision: string }): { failed: boolean; revision: string } | null {
    return props.revision === state.revision ? null : { failed: false, revision: props.revision };
  }
  override componentDidCatch(): void { this.props.onError(); }
  override render(): ReactNode {
    return this.state.failed ? <p className="m-0 p-4 text-sm text-muted-foreground" role="status">{this.props.message}</p> : this.props.children;
  }
}

/** Every artifact version the conversation's tool results produced (the version switcher's source), oldest first. */
export function useArtifactVersions(controller: ChatController | undefined, detect?: ArtifactsConfig['detect']): ArtifactDescriptor[] {
  const view = useSyncExternalStore(controller ? controller.subscribe : NOOP, () => controller?.getSnapshot().view, () => undefined);
  return useMemo(() => collectArtifacts(view, detect), [view, detect]);
}

/** How many messages the person has sent in the conversation: it changes when a new turn starts. */
export function useTurn(controller: ChatController | undefined): number {
  const view = useSyncExternalStore(controller ? controller.subscribe : NOOP, () => controller?.getSnapshot().view, () => undefined);
  return useMemo(() => (view?.entries ?? []).reduce((count, entry) => count + (entry.model ?? []).filter(message => message.role === 'user').length, 0), [view]);
}

/** The revisions the workspace provider retains for a file with their save times, newest first; followed while the panel is open. */
function useHistory(history: ViewerOptions['history'], path: string): readonly SavedRevision[] {
  const [revisions, setRevisions] = useState<readonly SavedRevision[]>([]);
  useEffect(() => {
    if (!history) return;
    let cancelled = false;
    const key = (saves: readonly SavedRevision[]) => saves.map(save => `${save.revision}@${save.savedAt}`).join();
    const load = () => history(path).then(saves => { if (!cancelled) setRevisions(current => key(current) === key(saves) ? current : saves); }).catch(() => {});
    void load();
    const timer = setInterval(load, POLL_MS);
    return () => { cancelled = true; clearInterval(timer); };
  }, [history, path]);
  return revisions;
}

interface VersionMenu {
  readonly items: readonly ViewerVersion[];
  readonly current: string;
  /** Position counted from the oldest retained revision: only a test hook. */
  readonly number: number | undefined;
  readonly savedAt: number | undefined;
}

/** The version menu, newest first: each retained revision is named by when it was saved, and the newest is "Latest". The pin is the revision. */
function versionChoices(artifact: ArtifactDescriptor, follow: boolean, revisions: readonly SavedRevision[], earlier: string): VersionMenu {
  const at = follow ? 0 : revisions.findIndex(save => save.revision === artifact.revision);
  const shown = at < 0 ? undefined : revisions[at];
  return { items: revisions.map((save, index) => ({ id: index === 0 ? 'latest' : save.revision, label: savedLabel(save.savedAt, Date.now(), earlier), savedAt: save.savedAt, ...(save.source ? { source: save.source } : {}), latest: index === 0 })),
    current: follow ? 'latest' : artifact.revision, number: shown ? revisions.length - at : undefined, savedAt: shown?.savedAt };
}

type DocumentController = MarkdownController | HtmlController;

/** One artifact version's frame and body. Mounted per resource and revision, so switching version starts clean. */
function Version({ artifact, pinned, menu, options, onSelect, onClose, headerStart }: {
  readonly artifact: ArtifactDescriptor; readonly pinned: boolean; readonly menu: VersionMenu; readonly options: ViewerOptions;
  readonly onSelect: (value: string) => void; readonly onClose: () => void; readonly headerStart?: ReactNode;
}) {
  const { type } = artifact;
  const chatText = useChatText();
  const { client, identity } = options;
  const { labels } = useAppText();
  const path = artifact.target.resource.path;
  const [ready, setReady] = useState<{ revision: string | undefined; text: string }>();
  const [kindMenu, setKindMenu] = useState<readonly ViewerMenuItem[]>([]);
  const [kindControls, setKindControls] = useState<ReactNode>();
  // The revision a lazily loaded view has mounted: the panel acknowledges a `present` only once the view is on screen, not while it loads.
  const [mounted, setMounted] = useState<string>();
  const kinds = options.kinds ?? noKinds;
  // The kinds that draw (an editor, a renderer or a lazily loaded view); a label-only kind names the artifact but leaves the drawing to the
  // next match. Image and PDF kinds read bytes: the file viewer draws them, never the artifact panel.
  const drawingKinds = useMemo(() => kinds.filter(kind => drawsText(kind)), [kinds]);
  // A kind's file may link to another file of the same workspace (a maquette's diagram): read its latest revision as text.
  const read = useCallback(async (other: string) => {
    const result = await client.read({ target: { ...artifact.target, resource: { ...artifact.target.resource, path: other } }, revision: { kind: 'latest' } }).catch(() => undefined);
    return result?.kind === 'available' ? readText(result.snapshot.bytes) : undefined;
  }, [client, artifact.target]);
  const fragment = useSyncExternalStore(subscribeHash, readHash, () => '');
  // A host viewer for the type (`viewers`) wins over a document kind (a `fallback` one), not over any other kind.
  const draws = artifactKind(artifact, drawingKinds);
  const custom = draws && !draws.fallback ? undefined : options.viewers?.[type];
  const drawing = custom ? undefined : draws;
  const editor = isEditorKind(drawing) ? drawing.editor : undefined;
  const create = useMemo(() => {
    const base = (snapshot: ResourceSnapshot) => ({ identity, client, instanceId: randomUUID(), epoch: 'workspace', source: { kind: 'saved' as const, snapshot } });
    if (editor === 'markdown') return (snapshot: ResourceSnapshot): DocumentController => createMarkdownController({ ...base(snapshot), readOnly: pinned });
    if (editor === 'html') return (snapshot: ResourceSnapshot): DocumentController => createHtmlController({ ...base(snapshot), readOnly: true });
    return undefined;
  }, [editor, pinned, client, identity]);
  const autosave = useRef<{ controller: DocumentController; flush: () => Promise<boolean> } | null>(null);
  const saved = useSaved<DocumentController>({ client, target: artifact.target, revision: pinned ? artifact.revision : undefined, create,
    beforeDispose: controller => autosave.current?.controller === controller ? autosave.current.flush() : undefined });
  const controller = saved.controller;
  const registerAutosave = useCallback((flush: (() => Promise<boolean>) | null) => {
    autosave.current = flush && controller ? { controller, flush } : null;
  }, [controller]);
  useLayoutEffect(() => {
    if (!controller) return;
    const notify = () => {
      const state = controller.getSnapshot();
      options.onUnsavedChange?.(state.dirty || state.save.kind === 'pending' || state.save.kind === 'settled' && state.save.result.kind === 'unknown');
    };
    notify(); const stop = controller.subscribe(notify);
    return () => { stop(); options.onUnsavedChange?.(false); };
  }, [controller, options.onUnsavedChange]);
  // The text to copy and download is the buffer when a viewer holds one, so the person's unsaved edits are included.
  const text = useSyncExternalStore(controller ? controller.subscribe : NOOP, () => controller ? controller.getSnapshot().text : saved.text, () => saved.text);
  const extension = EXTENSION.exec(path)?.[1] ?? 'txt';
  const revision = saved.kind === 'open' ? saved.snapshot.ref.revision : pinned ? artifact.revision : undefined;
  // A host viewer and the canvas (which shows only a "no viewer" note) never report a mount: a presented file in them stays unconfirmed.
  // A kind that waits for ready (a dashboard loading its data, the sandboxed mock-up) reports only once its renderer called `onReady` for this text.
  // A lazily loaded view (every built-in viewer) reports only once it has loaded and mounted for this revision.
  const waits = !!(drawing && 'waitsForReady' in drawing && drawing.waitsForReady);
  const suspends = !!drawing && (!editor || !!controller);
  const opened = saved.kind === 'open' ? saved.snapshot.ref.revision : undefined;
  useReportShown(options.onShown, path, !custom && type !== 'canvas' && opened !== undefined && (!suspends || mounted === opened) && (!waits || ready !== undefined && ready.revision === revision && ready.text === saved.text) ? opened : undefined);
  const onFailedOption = options.onFailed;
  const reportFailed = useCallback((reason: string) => {
    setReady(undefined);
    if (revision !== undefined) onFailedOption?.({ path, revision, reason });
  }, [onFailedOption, path, revision]);
  // Choosing newest follows live saves; Current marks the displayed revision.
  const versions = menu.items.length > 1 ? <ViewerVersions testId="artifact-versions" current={menu.current} onSelect={onSelect} versions={menu.items} /> : undefined;
  const loading = <ViewLoading label={labels.loading} />;
  const target = { artifact: artifactKey(artifact), version: pinned ? artifact.revision : 'latest' };
  const frame = {
    title: artifact.title, testId: 'artifact', titleTestId: 'artifact-panel-title', controls: versions, onClose, target, ...(headerStart ? { headerStart } : {}), ...(revision === undefined ? {} : { revision }), ...(options.share ? { onShare: options.share } : {}),
    subtitle: <>
      <span title={path}>{path}</span><span aria-hidden="true">·</span>
      <span data-testid="artifact-panel-type">{typeLabel(artifact, kinds, chatText.labels.artifactTypes)}</span>
      <span aria-hidden="true">·</span>
      <span data-testid="artifact-panel-version">{pinned ? (menu.savedAt !== undefined ? labels.savedAt(savedLabel(menu.savedAt, Date.now(), labels.earlierVersion)) : labels.olderVersion) : menu.savedAt ? labels.latestSavedAt(savedLabel(menu.savedAt, Date.now(), labels.earlierVersion)) : labels.latest}</span>
    </>,
    ...(pinned ? { status: { label: labels.readOnly, kind: 'read-only' as const } } : {}),
  };
  const filename = `${artifact.title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '') || 'artifact'}.${extension}`;
  const body = (children: ReactNode) => <div data-testid="artifact-body" data-state={saved.kind} className="flex h-full min-h-0 flex-1 flex-col overflow-hidden">{children}</div>;
  if (custom) return body(custom({ target: artifact.target, title: artifact.title, ...(pinned ? { revision: artifact.revision } : {}), frame: { testId: 'artifact', titleTestId: 'artifact-panel-title', controls: versions, onClose, target, ...(headerStart ? { headerStart } : {}) } }));
  // Until the version is open the bar offers no Share: the pane that shows it brings its own frame, so this one is replaced (remounted)
  // when it opens, and a Share pressed just then would copy the link with its "Link copied" notice lost with the old frame.
  if (saved.kind !== 'open') {
    const { onShare: _, ...waiting } = frame;
    return body(<ViewerFrame {...waiting}><p className="m-0 p-4 text-sm text-muted-foreground" role="status">{saved.kind === 'loading' ? labels.loading : saved.kind === 'invalid' ? labels.artifactNotText : labels.versionUnavailable}</p></ViewerFrame>);
  }
  const document = (children: ReactNode) => <div data-testid="document" data-revision={saved.snapshot.ref.revision} className="flex h-full min-h-0 flex-col">
    {pinned && <><p role="note" data-testid="version-view-only" className="m-0 shrink-0 bg-muted/30 px-3 py-2 text-xs text-muted-foreground">{labels.versionViewOnly}</p><Separator /></>}
    <div className="min-h-0 flex-1">{children}</div>
  </div>;
  if (isEditorKind(drawing) && controller) {
    // The pane brings its own bar; while it loads, the same bar without Share shows a spinner. Its test ids are `artifact-pending-*`, so a
    // test (or a script) waiting for `artifact-more` reaches the pane's own menu, not the one of a bar about to be replaced.
    const { onShare: _, ...waiting } = { ...frame, testId: 'artifact-pending' };
    let pane: ReactNode;
    if (drawing.editor === 'markdown') {
      const MarkdownPane = lazyView(drawing.load);
      pane = <MarkdownPane controller={controller as MarkdownController} initialMode="rich" onAutosaveChange={registerAutosave} onBeforeLeaveChange={options.onBeforeLeaveChange} {...frame} />;
    } else {
      const HtmlPane = lazyView(drawing.load);
      pane = <HtmlPane controller={controller as HtmlController} {...(options.interactive ? { interactive: options.interactive } : {})} {...frame} />;
    }
    return body(document(<Suspense fallback={<ViewerFrame {...waiting}>{loading}</ViewerFrame>}>{pane}<Mounted value={saved.snapshot.ref.revision} onMount={setMounted} /></Suspense>));
  }
  const actions = { onCopy: () => copyText(text ?? ''), onDownload: () => downloadFile(filename, text ?? '', `${artifact.mediaType};charset=utf-8`) };
  if (drawing && !isEditorKind(drawing) && !isMediaKind(drawing)) {
    const render = ('renderer' in drawing ? drawing.renderer : undefined) ?? lazyRenderer(drawing.load!);
    return body(<ViewerFrame {...frame} {...actions} controls={<>{kindControls}{versions}</>} menu={kindMenu}><div data-testid="artifact-kind-view" className="min-h-0 flex-1 overflow-auto">
      <KindBoundary revision={saved.snapshot.ref.revision} message={labels.versionUnavailable} onError={() => reportFailed('the view failed to render')}>
        <Suspense fallback={loading}>
          <KindView render={render} props={{ artifact, text: saved.text, revision: saved.snapshot.ref.revision, pinned, fragment, read, onReady: () => setReady({ revision, text: saved.text }), onFailed: reportFailed, setMenu: setKindMenu, setControls: setKindControls }} />
          <Mounted value={saved.snapshot.ref.revision} onMount={setMounted} />
        </Suspense>
      </KindBoundary>
    </div></ViewerFrame>);
  }
  if (type === 'canvas') return body(<ViewerFrame {...frame}><p className="m-0 p-4 text-sm text-muted-foreground" role="status">{labels.noCanvasViewer}</p></ViewerFrame>);
  return body(<ViewerFrame {...frame} {...actions}><div className="min-h-0 flex-1 overflow-auto p-3"><CodeBlock code={saved.text} language={artifact.language ?? 'text'} /></div></ViewerFrame>);
}

/**
 * One artifact in the panel. `active.follow` shows the latest saved revision under the newest known title (`versions`: every version of
 * this file the conversation presented or saved, newest first); otherwise the one revision in `active.descriptor` is pinned and read-only.
 * `onSelect` receives `latest` or a revision from the version menu.
 */
export function ArtifactPanel({ active, versions, options, onSelect, onClose, headerStart }: {
  readonly active: { readonly descriptor: ArtifactDescriptor; readonly follow: boolean };
  readonly versions: readonly ArtifactDescriptor[];
  readonly options: ViewerOptions;
  readonly onSelect: (value: string) => void;
  readonly onClose: () => void;
  /** A leading control in the bar, such as a back button (a file opened from a list). */
  readonly headerStart?: ReactNode;
}) {
  const { follow } = active;
  const artifact = follow ? versions[0] ?? active.descriptor : active.descriptor;
  const path = artifact.target.resource.path;
  const revisions = useHistory(options.history, path);
  const { labels } = useAppText();
  const menu = versionChoices(artifact, follow, revisions, labels.earlierVersion);
  return <div data-testid="artifact-panel" data-artifact-id={artifactKey(artifact)} data-artifact-type={artifact.type} data-follow={follow ? 'true' : 'false'} data-artifact-position={menu.number} data-artifact-revision={follow ? undefined : artifact.revision}
    className="pi-chat flex h-full min-h-0 flex-col">
    <Version key={`${path}@${follow ? 'latest' : artifact.revision}`} artifact={artifact} pinned={!follow} menu={menu} options={options} onSelect={onSelect} onClose={onClose} {...(headerStart ? { headerStart } : {})} />
  </div>;
}

'use client';

// Opens one workspace file in the viewer its kind names (`ViewerOptions.kinds`), always in the standard viewer frame (viewer-frame item):
// Markdown and HTML in their editors (revisioned through the host's resource client, so saves go back to the file and an edit made behind
// the editor's back is a conflict), images and PDFs read-only from the file's bytes, a drawing kind in the artifact panel, anything else as
// text. Each viewer loads the first time its kind opens. A host viewer (`viewers[kind]`) wins over a document kind.
import { Suspense, useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import type { ReactNode } from 'react';
import { DownloadIcon } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { randomUUID } from '@hachej/boring-files/platform';
import type { ResourceLocator, ResourceSnapshot } from '@hachej/boring-files';
import { createMarkdownController } from '@hachej/boring-ui-kit/markdown';
import type { MarkdownController } from '@hachej/boring-ui-kit/markdown';
import { createHtmlController } from '@hachej/boring-ui-kit/html';
import type { HtmlController } from '@hachej/boring-ui-kit/html';
import { ViewerFrame } from '../viewer-frame/viewer-frame';
import { downloadFile } from '../viewer-frame/download';
import { formatBytes } from '../viewer-frame/media';
import { copyText } from '../utils/utils';
import { mediaTypeOf, viewerKindOf } from '@hachej/boring-files/file-types';
import { isBlobPointerPath, resolveBlobPointer } from '@hachej/boring-files/blob';
import type { BlobItem } from '@hachej/boring-files/blob';
import type { ViewerKind as FileKind } from '@hachej/boring-files/file-types';
import { KIND_LABEL, decodeText } from './file-kinds';
import { ArtifactPanel, useReportShown } from './artifact-panel';
import { artifactKind } from '../pi-artifacts/artifact';
import type { ArtifactDescriptor, ArtifactType } from '../pi-artifacts/artifact';
import { Mounted, ViewLoading, drawsText, isEditorKind, isMediaKind, lazyView, noKinds } from './viewer-kinds';
import type { EditorKind, MediaKind, PanelKind } from './viewer-kinds';
import type { ViewerOptions } from './artifact-panel';
import { useSaved } from './use-saved';
import { useAppText } from './app-labels';

const POLL_MS = 1500;
const nameOf = (path: string) => path.split('/').pop() || path;

interface Common {
  readonly path: string;
  readonly kind: FileKind;
  readonly locator: ResourceLocator;
  readonly options: ViewerOptions;
  readonly onClose: () => void;
  readonly back: ReactNode;
  readonly onUnsavedChange?: ((unsaved: boolean) => void) | undefined;
  readonly onBeforeLeaveChange?: ((flush: (() => Promise<boolean>) | null) => void) | undefined;
}

const FILE_TYPE: Partial<Record<FileKind, ArtifactType>> = { markdown: 'markdown', html: 'html' };
/** A file as the artifact its kind sees: the same descriptor a `present` of it would carry, so one kind match serves every way of opening a file. */
const fileArtifact = (path: string, locator: ResourceLocator): ArtifactDescriptor => ({ schema: 'boring.artifact', version: 1, title: nameOf(path), type: FILE_TYPE[viewerKindOf(path)] ?? 'code', mediaType: mediaTypeOf(path), target: locator, revision: 'latest' });
/** The image or PDF kind of a media type (a file's, or a large file's behind a pointer). */
const mediaKindOf = (kinds: readonly PanelKind[], artifact: ArtifactDescriptor): MediaKind | undefined => artifactKind(artifact, kinds.filter(isMediaKind));

const subtitleOf = (locator: ResourceLocator) => <span data-testid="file-path" className="truncate">{locator.resource.path}</span>;

/** Markdown or HTML: a revisioned controller over the file. A new revision remounts the pane; it starts in the mode the person chose. */
function FileDocument({ path, editor, locator, options, onClose, back, onUnsavedChange, onBeforeLeaveChange }: Common & { readonly editor: EditorKind }) {
  const { client, identity } = options;
  const markdown = editor.editor === 'markdown';
  const create = useMemo(() => (snapshot: ResourceSnapshot): MarkdownController | HtmlController => (markdown ? createMarkdownController : createHtmlController)({
    identity, client, instanceId: randomUUID(), epoch: 'workspace', source: { kind: 'saved', snapshot } }), [markdown, client, identity]);
  const autosave = useRef<{ controller: MarkdownController | HtmlController; flush: () => Promise<boolean> } | null>(null);
  const saved = useSaved({ client, target: locator, create, beforeDispose: controller => autosave.current?.controller === controller ? autosave.current.flush() : undefined });
  const registerAutosave = useCallback((flush: (() => Promise<boolean>) | null) => {
    autosave.current = flush && saved.controller ? { controller: saved.controller, flush } : null;
  }, [saved.controller]);
  useLayoutEffect(() => {
    const controller = saved.controller;
    if (!controller) return;
    const notify = () => {
      const snapshot = controller.getSnapshot();
      onUnsavedChange?.(snapshot.dirty || snapshot.save.kind === 'pending'
        || (snapshot.save.kind === 'settled' && snapshot.save.result.kind === 'unknown'));
    };
    notify();
    const unsubscribe = controller.subscribe(notify);
    return () => { unsubscribe(); onUnsavedChange?.(false); };
  }, [saved.controller, onUnsavedChange]);
  const { labels } = useAppText();
  const [mode, setMode] = useState<string>(markdown ? 'rich' : 'preview');
  const [formattingToolbar, setFormattingToolbar] = useState<'selection' | 'pinned'>('selection');
  // The editor loads the first time a document opens: the file counts as shown once it has mounted.
  const [mounted, setMounted] = useState<string>();
  const opened = saved.kind === 'open' && saved.controller ? saved.snapshot.ref.revision : undefined;
  useReportShown(options.onShown, path, opened !== undefined && mounted === opened ? opened : undefined);
  const common = { title: nameOf(path), subtitle: subtitleOf(locator), target: { file: path }, onClose, titleTestId: 'file-title', headerStart: back, ...(options.share ? { onShare: options.share } : {}) };
  // Until the document is open the bar offers no Share, Copy or menu actions of its own: they would act on a document that is not shown.
  if (saved.kind !== 'open' || !saved.controller) {
    return <ViewerFrame title={common.title} subtitle={common.subtitle} onClose={onClose} headerStart={back}>
      <p role="status" className="m-0 p-4 text-sm text-muted-foreground">{saved.kind === 'loading' ? labels.loading : saved.kind === 'missing' ? labels.fileMissing : labels.fileNotText}</p>
    </ViewerFrame>;
  }
  const revision = saved.snapshot.ref.revision;
  // The preview selector the journeys use keeps working: the wrapper holds the document's text.
  let pane: ReactNode;
  if (editor.editor === 'markdown') {
    const MarkdownPane = lazyView(editor.load);
    pane = <MarkdownPane key={revision} controller={saved.controller as MarkdownController} revision={revision} initialMode={mode as 'rich'} onModeChange={setMode} formattingToolbar={formattingToolbar} onFormattingToolbarChange={setFormattingToolbar} onAutosaveChange={registerAutosave} onBeforeLeaveChange={onBeforeLeaveChange} {...common} />;
  } else {
    const HtmlPane = lazyView(editor.load);
    pane = <HtmlPane key={revision} controller={saved.controller as HtmlController} revision={revision} initialMode={mode as 'preview'} onModeChange={setMode} {...(options.interactive ? { interactive: options.interactive } : {})} {...common} />;
  }
  return <div data-testid="file-preview" className="h-full min-h-0" data-revision={revision}>
    <Suspense fallback={<ViewerFrame testId="viewer-pending" title={common.title} subtitle={common.subtitle} onClose={onClose} headerStart={back}><ViewLoading label={labels.loading} /></ViewerFrame>}>
      {pane}<Mounted value={revision} onMount={setMounted} />
    </Suspense>
  </div>;
}

/** Native controls only. A failed codec leaves a download instead of a broken video box. */
function VideoPreview({ item }: { readonly item: BlobItem }) {
  const [failed, setFailed] = useState(false);
  const { labels } = useAppText();
  return <div className="flex min-h-0 min-w-0 flex-1 items-center justify-center">
    {failed ? <div className="flex flex-col items-center gap-3 p-4">
      <p role="status" data-testid="video-unplayable" className="text-muted-foreground">{labels.videoUnreadable}</p>
      <Button nativeButton={false} render={<a href={item.url} download={item.name} />} data-testid="video-download">{labels.download}</Button>
    </div> : <video src={item.url} aria-label={item.name} controls playsInline preload="metadata" onError={() => setFailed(true)} className="h-full max-h-full w-full min-w-0 object-contain" />}
  </div>;
}

/**
 * A large file behind a pointer, from the host's URL: images, PDFs and videos inline, anything else as a download.
 * The viewers get a URL; none reads the media bytes into the page.
 */
function BlobFile({ item, subtitle, media, ...common }: { readonly item: BlobItem; readonly subtitle: ReactNode; readonly media: MediaKind | undefined; readonly onClose: () => void; readonly onRefresh: () => unknown; readonly target: unknown; readonly titleTestId: string; readonly headerStart: ReactNode; readonly onShare?: NonNullable<ViewerOptions['share']> }) {
  const { labels } = useAppText();
  const details = <>{subtitle}<span aria-hidden="true">·</span><span>{formatBytes(item.size)}</span></>;
  if (media?.media === 'image') { const ImagePane = lazyView(media.load); return <ImagePane name={item.name} mediaType={item.type} url={item.url} subtitle={details} {...common} />; }
  if (media?.media === 'pdf') { const PdfPane = lazyView(media.load); return <PdfPane name={item.name} url={item.url} subtitle={subtitle} {...common} />; }
  if (item.type.startsWith('video/')) return <ViewerFrame title={item.name} subtitle={details} {...common} onDownload={() => {
    const link = Object.assign(document.createElement('a'), { href: item.url, download: item.name });
    document.body.append(link); link.click(); link.remove();
  }}><VideoPreview key={item.url} item={item} /></ViewerFrame>;
  return <ViewerFrame title={item.name} subtitle={details} {...common}>
    <div data-testid="blob-file" data-blob-type={item.type} className="m-auto flex flex-col items-center gap-3 p-6 text-center">
      <p className="m-0 text-sm text-muted-foreground">{item.type}</p>
      <Button nativeButton={false} render={<a href={item.url} download={item.name} />} data-testid="blob-download"><DownloadIcon data-icon="inline-start" aria-hidden="true" />{labels.download}</Button>
    </div>
  </ViewerFrame>;
}

type Loaded = { readonly kind: 'loading' | 'missing' } | { readonly kind: 'ready'; readonly bytes: Uint8Array; readonly revision: string; readonly text: string | undefined };

/** Image, PDF and text files: read through the resource client, refreshed on demand (and followed while open, for text). */
function FileBytes({ path, kind, locator, options, onClose, back, media }: Common & { readonly media: MediaKind | undefined }) {
  const { labels } = useAppText();
  // An image or PDF pane loads the first time one opens: the file counts as shown once it has mounted.
  const [mounted, setMounted] = useState<string>();
  const targetKey = JSON.stringify(locator);
  const binding = useMemo(() => ({ client: options.client, locator, path }), [options.client, targetKey, path]); // eslint-disable-line react-hooks/exhaustive-deps
  const [stored, setStored] = useState<{ readonly binding: typeof binding; readonly value: Loaded }>();
  const file: Loaded = stored?.binding === binding ? stored.value : { kind: 'loading' };
  const running = useRef<AbortController | undefined>(undefined);
  const load = useCallback(async () => {
    running.current?.abort();
    const abort = new AbortController(); running.current = abort;
    try {
      const read = await binding.client.read({ target: binding.locator, revision: { kind: 'latest' } }, abort.signal);
      if (abort.signal.aborted || running.current !== abort) return;
      if (read.kind !== 'available') {
        setStored(current => current?.binding === binding && current.value.kind === 'ready' ? current : { binding, value: { kind: 'missing' } });
        return;
      }
      const { bytes, ref } = read.snapshot;
      setStored({ binding, value: { kind: 'ready', bytes, revision: ref.revision, text: decodeText(binding.path, bytes) } });
    } catch {
      if (!abort.signal.aborted && running.current === abort) setStored(current => current?.binding === binding && current.value.kind === 'ready' ? current : { binding, value: { kind: 'missing' } });
    }
  }, [binding]);
  useEffect(() => {
    void load();
    const timer = kind === 'text' ? setInterval(() => { void load(); }, POLL_MS) : undefined;
    return () => { running.current?.abort(); clearInterval(timer); };
  }, [load, kind]);
  // A pointer file is resolved here, where it is read, once per read: the viewers below receive the item, never the pointer.
  const blob = useMemo(() => file.kind === 'ready' && isBlobPointerPath(path) ? resolveBlobPointer(file.bytes, options.blobBase) : undefined, [file, path, options.blobBase]);
  // A lazily loaded pane (an image, a PDF, a large file's viewer) counts as shown once it has mounted; the text view at once.
  const lazyPane = blob?.kind === 'blob' || !blob && !!media;
  useReportShown(options.onShown, path, file.kind === 'ready' && (!lazyPane || mounted === file.revision) ? file.revision : undefined);
  const common = { subtitle: subtitleOf(locator), target: { file: path }, onClose, titleTestId: 'file-title', headerStart: back, ...(options.share ? { onShare: options.share } : {}) };
  // Until the file is read the bar offers no Share: the image and PDF panes bring their own frame, so this one is replaced (remounted)
  // when the bytes arrive, and a Share pressed just then would copy the link with its "Link copied" notice lost with the old frame.
  if (file.kind !== 'ready') {
    return <ViewerFrame title={nameOf(path)} subtitle={common.subtitle} onClose={onClose} titleTestId="file-title" headerStart={back}>
      <p role="status" className="m-0 p-4 text-sm text-muted-foreground">{file.kind === 'loading' ? labels.loading : labels.fileMissing}</p>
    </ViewerFrame>;
  }
  // The bar while a view loads: `viewer-pending-*` test ids, so `viewer-more` is the view's own menu.
  const loading = <ViewerFrame testId="viewer-pending" title={nameOf(path)} subtitle={common.subtitle} onClose={onClose} titleTestId="file-title" headerStart={back}><ViewLoading label={labels.loading} /></ViewerFrame>;
  const shown = <Mounted value={file.revision} onMount={setMounted} />;
  if (blob?.kind === 'blob') {
    const blobMedia = mediaKindOf(options.kinds ?? noKinds, { ...fileArtifact(path, locator), mediaType: blob.item.type });
    return <Suspense fallback={loading}><BlobFile item={blob.item} media={blobMedia} onRefresh={load} {...common} />{shown}</Suspense>;
  }
  if (media?.media === 'image') { const ImagePane = lazyView(media.load); return <Suspense fallback={loading}><ImagePane name={nameOf(path)} mediaType={mediaTypeOf(path)} bytes={file.bytes} onRefresh={load} {...common} />{shown}</Suspense>; }
  if (media?.media === 'pdf') { const PdfPane = lazyView(media.load); return <Suspense fallback={loading}><PdfPane name={nameOf(path)} bytes={file.bytes} onRefresh={load} {...common} />{shown}</Suspense>; }
  const { text } = file, size = file.bytes.byteLength;
  return <ViewerFrame title={nameOf(path)} {...common} subtitle={<>{subtitleOf(locator)}<span aria-hidden="true">·</span><span>{formatBytes(size)}</span></>}
    onRefresh={load} {...(text === undefined ? {} : { onCopy: () => copyText(text), onDownload: () => downloadFile(nameOf(path), text, 'text/plain;charset=utf-8') })}>
    {blob?.kind === 'unsupported-version' && <p role="note" data-testid="blob-newer-format" className="m-0 px-3 pt-3 text-sm text-muted-foreground">{labels.newerBlobFormat}</p>}
    {text === undefined
      ? <p role="status" className="m-0 p-4 text-sm text-muted-foreground">{labels.binaryFile(formatBytes(size))}</p>
      : <div className="min-h-0 flex-1 overflow-auto p-3"><pre data-testid="file-preview" className="m-0 font-mono text-sm leading-relaxed break-words whitespace-pre-wrap">{text}</pre></div>}
  </ViewerFrame>;
}

/**
 * One file in the panel. `path` is the host's name for it (shown in the share target and `data-path`); `locator` is the resource the
 * client reads. Remount per file with a `key`. `onBack` adds a back button to the bar (for example to the host's file list).
 */
export function FileViewer({ path, locator, options, onClose, onBack, backLabel, onUnsavedChange, onBeforeLeaveChange }: {
  readonly path: string;
  readonly locator: ResourceLocator;
  readonly options: ViewerOptions;
  readonly onClose: () => void;
  readonly onBack?: (() => void) | undefined;
  readonly backLabel?: string | undefined;
  /** Built-in editable viewers report unsaved and unconfirmed changes for navigation guards. */
  readonly onUnsavedChange?: ((unsaved: boolean) => void) | undefined;
  /** The Markdown autosave barrier, for flush-before-navigation guards. Null for explicit-save viewers. */
  readonly onBeforeLeaveChange?: ((flush: (() => Promise<boolean>) | null) => void) | undefined;
}) {
  const kind = viewerKindOf(path);
  const { labels, icons } = useAppText();
  const back = onBack ? <Button variant="ghost" size="sm" data-testid="file-back" aria-label={backLabel ?? labels.back} title={backLabel ?? labels.back} onClick={onBack} className="shrink-0"><icons.back data-icon="inline-start" aria-hidden="true" /><span className="max-sm:sr-only">{backLabel ?? labels.back}</span></Button> : undefined;
  const common: Common = { path, kind, locator, options, onClose, back, onUnsavedChange, onBeforeLeaveChange };
  const locatorKey = JSON.stringify(locator);
  const artifact = useMemo(() => fileArtifact(path, locator), [path, locatorKey]); // eslint-disable-line react-hooks/exhaustive-deps
  // One resolution through the kinds, whoever opened the file: a host viewer for the file kind wins over a document kind (a `fallback`
  // one), not over any other kind. A drawing kind (a maquette, a diagram, an app's) shows the file in the artifact panel.
  const kinds = options.kinds ?? noKinds;
  const found = artifactKind(artifact, kinds.filter(entry => drawsText(entry) || isMediaKind(entry)));
  const custom = found && !found.fallback ? undefined : options.viewers?.[kind];
  const resolved = custom ? undefined : found;
  const drawn = resolved && !isEditorKind(resolved) && !isMediaKind(resolved) ? artifact : undefined;
  if (drawn) return <div data-testid="file-viewer" data-kind="artifact" data-path={path} aria-label={labels.fileViewer(drawn.title)} className="flex h-full min-h-0 flex-col overflow-hidden [&>*]:min-h-0 [&>*]:flex-1">
    <ArtifactPanel active={{ descriptor: drawn, follow: true }} versions={[]} options={options} onSelect={() => {}} onClose={onClose} headerStart={back} />
  </div>;
  return <div data-testid="file-viewer" data-kind={kind} data-path={path} aria-label={labels.fileViewer(KIND_LABEL[kind])} className="flex h-full min-h-0 flex-col overflow-hidden [&>*]:min-h-0 [&>*]:flex-1">
    {custom ? custom({ target: locator, title: nameOf(path), frame: { titleTestId: 'file-title', onClose, target: { file: path }, headerStart: back } })
      : isEditorKind(resolved) ? <FileDocument {...common} editor={resolved} />
      // The resource client supplies bytes, not a streaming URL. Unlike images, videos must not be buffered to make an object URL.
      : kind === 'video' ? <ViewerFrame title={nameOf(path)} subtitle={subtitleOf(locator)} onClose={onClose} headerStart={back}><p role="status" className="m-0 p-4 text-sm text-muted-foreground">{labels.fileNotText}</p></ViewerFrame>
      : kind === 'canvas' ? <ViewerFrame title={nameOf(path)} subtitle={subtitleOf(locator)} onClose={onClose} headerStart={back}><p role="status" className="m-0 p-4 text-sm text-muted-foreground">{labels.noCanvasViewer}</p></ViewerFrame>
      : <FileBytes {...common} media={isMediaKind(resolved) ? resolved : undefined} />}
  </div>;
}

import { isBinaryKind } from '@hachej/boring-files/file-types';
import type { ViewerKind } from '@hachej/boring-files/file-types';

/** The viewer kinds, media types and extensions live in `@hachej/boring-files/file-types`; this keeps only what the viewers show. */
export const KIND_LABEL: Readonly<Record<ViewerKind, string>> = { markdown: 'Markdown', html: 'HTML', canvas: 'Canvas', image: 'Image', pdf: 'PDF', video: 'Video', text: 'Text' };

/** The text of a file, or `undefined` when it is binary: an image, PDF or video kind (SVG excepted), a NUL byte, or bytes that are not UTF-8. */
export function decodeText(path: string, bytes: Uint8Array): string | undefined {
  if (isBinaryKind(path) || bytes.includes(0)) return undefined;
  try { return new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(bytes); } catch { return undefined; }
}

import { useEffect, useLayoutEffect, useMemo, useState } from 'react';
import type { ResourceClient, ResourceLocator, ResourceSnapshot } from '@hachej/boring-files';

const POLL_MS = 1500;
export const readText = (bytes: Uint8Array): string | undefined => { try { return new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(bytes); } catch { return undefined; } };

/** What a viewer controller exposes to `useSaved`: its buffer state (never replaced while dirty or saving) and teardown. */
export interface SavedController {
  readonly getSnapshot: () => { readonly dirty?: boolean; readonly save?: { readonly kind: string }; readonly base?: { readonly kind: string; readonly target?: object } };
  readonly dispose: () => void;
}

export type SavedState<C extends SavedController> =
  | { readonly kind: 'loading' | 'missing' | 'denied' | 'unavailable' | 'invalid'; readonly text?: undefined; readonly controller?: undefined }
  | { readonly kind: 'open'; readonly snapshot: ResourceSnapshot; readonly text: string; readonly controller: C | undefined };

/**
 * The saved text of one resource: the latest revision (polled while the local buffer is clean, never replacing unsaved
 * edits) or one exact revision read once. `create` may return a viewer controller for each saved snapshot; it is disposed when
 * a newer revision replaces it and on unmount.
 */
export function useSaved<C extends SavedController = SavedController>({ client, target, revision, create, beforeDispose }: {
  readonly client: ResourceClient;
  readonly target: ResourceLocator;
  readonly revision?: string | undefined;
  readonly create?: ((snapshot: ResourceSnapshot) => C) | undefined;
  /** Owner teardown may wait for an editor's final conditional flush. Unsubscribe remains synchronous. */
  readonly beforeDispose?: ((controller: C) => Promise<unknown> | undefined) | undefined;
}): SavedState<C> {
  const key = JSON.stringify([target.resource.providerId, target.resource.path, target.view.kind, target.view.kind === 'working' ? target.view.viewId : null, revision]);
  const binding = useMemo(() => ({ client, key, create, beforeDispose }), [client, key]); // eslint-disable-line react-hooks/exhaustive-deps
  useLayoutEffect(() => { binding.create = create; binding.beforeDispose = beforeDispose; }, [binding, create, beforeDispose]);
  const [stored, setStored] = useState<{ readonly binding: typeof binding; readonly state: SavedState<C> }>();
  useEffect(() => {
    let cancelled = false, reading = false;
    let state: SavedState<C> = { kind: 'loading' };
    const update = (next: SavedState<C>) => { state = next; setStored({ binding, state }); };
    update(state);
    const release = (controller: C | undefined) => {
      if (!controller) return;
      const flushing = binding.beforeDispose?.(controller);
      if (flushing) void flushing.finally(() => controller.dispose()).catch(() => {});
      else controller.dispose();
    };
    const follow = async () => {
      if (cancelled || reading) return;
      const now = state;
      const before = now.kind === 'open' ? now.controller?.getSnapshot() : undefined;
      if (before && (before.dirty || before.save?.kind === 'pending')) return;
      reading = true;
      let read;
      try { read = await client.read({ target, revision: revision ? { kind: 'exact', value: revision } : { kind: 'latest' } }).catch(() => undefined); }
      finally { reading = false; }
      if (cancelled || !read || state !== now) return;
      const local = now.kind === 'open' ? now.controller?.getSnapshot() : undefined;
      if (local !== before) return;
      if (read.kind !== 'available') { if (now.kind !== 'open') update({ kind: read.kind }); return; }
      if (now.kind === 'open') {
        if (now.snapshot.ref.revision === read.snapshot.ref.revision) return;
        if (local?.base?.kind === 'revision' && (local.base.target as { readonly revision?: string } | undefined)?.revision === read.snapshot.ref.revision) return;
        release(now.controller);
      }
      const text = readText(read.snapshot.bytes);
      if (text === undefined) { update({ kind: 'invalid' }); return; }
      let controller: C | undefined;
      try { controller = binding.create?.(read.snapshot); } catch { update({ kind: 'invalid' }); return; }
      update({ kind: 'open', snapshot: read.snapshot, text, controller });
    };
    void follow();
    const timer = revision ? undefined : setInterval(() => { void follow(); }, POLL_MS);
    return () => { cancelled = true; clearInterval(timer); release(state.controller); };
  }, [binding]); // eslint-disable-line react-hooks/exhaustive-deps
  return stored?.binding === binding ? stored.state : { kind: 'loading' };
}

/** A save time for a person: the clock time (with seconds, so two quick saves differ) today, the date as well on another day. */
export function savedLabel(savedAt: number | undefined, now = Date.now(), earlier = 'Earlier version'): string {
  if (!savedAt) return earlier;
  const day = (value: number) => new Date(value).toDateString();
  return new Date(savedAt).toLocaleString([], day(savedAt) === day(now) ? { timeStyle: 'medium' } : { dateStyle: 'medium', timeStyle: 'medium' });
}

import { useEffect, useState } from 'react';

export interface NewVersionOptions {
  /** The build this page runs, as the host bakes it into its bundle. `undefined`, empty or `dev` means no check. */
  readonly current: string | undefined;
  /** Where the deployed build is served, as `{ "build": "<id>" }`. Default `/version.json`. */
  readonly url?: string;
  /** How often to check, in milliseconds (default one minute). The check also runs when the tab becomes visible again. */
  readonly everyMs?: number;
}

/**
 * True once the served build differs from `current`: a tab left open keeps running the JavaScript it loaded, so a long-open page
 * learns that a newer deploy exists and offers a reload (`NewVersionNotice`). A failed check (offline, a bad response) is retried
 * on the next tick and never flips the result. Once true it stays true; the page is expected to reload.
 */
export function useNewVersion({ current, url = '/version.json', everyMs = 60_000 }: NewVersionOptions): boolean {
  const [stale, setStale] = useState(false);
  useEffect(() => {
    if (!current || current === 'dev') return undefined;
    let done = false;
    const check = async () => {
      if (done) return;
      try {
        const response = await fetch(url, { cache: 'no-store', credentials: 'same-origin' });
        if (response.ok && (await response.json()).build !== current) { done = true; setStale(true); }
      } catch { /* offline or not deployed yet: try again on the next check */ }
    };
    const visible = () => { if (document.visibilityState === 'visible') void check(); };
    const timer = setInterval(check, everyMs);
    document.addEventListener('visibilitychange', visible);
    return () => { done = true; clearInterval(timer); document.removeEventListener('visibilitychange', visible); };
  }, [current, url, everyMs]);
  return stale;
}

import { Button } from '@/components/ui/button';
import { Separator } from '@/components/ui/separator';
import { useAppText } from './app-labels';
import { cn } from '../utils/utils';

/**
 * The "a new version is available" notice: a status line with a Reload button. Render it while `useNewVersion` returns true
 * (`{stale && <NewVersionNotice />}`). Reload is `location.reload()`, so unsaved work in the page is lost: the host decides when to show it.
 */
export function NewVersionNotice({ className }: { readonly className?: string }) {
  const { labels } = useAppText();
  return (
    <div role="status" data-testid="new-version-notice" className={cn('relative flex flex-wrap items-center justify-between gap-3 bg-muted px-4 py-2 text-sm text-foreground', className)}>
      <Separator className="absolute inset-x-0 bottom-0" />
      <span>{labels.newVersion}</span>
      <Button variant="outline" size="sm" data-testid="new-version-reload" onClick={() => globalThis.location.reload()}>{labels.reload}</Button>
    </div>
  );
}

import { uploadPath } from '@hachej/boring-files/file-types';
import { randomUUID } from '@hachej/boring-files/platform';
import type { FileTreeController } from '@hachej/boring-ui-kit/file-tree';
import type { UploadResult } from '../pi-chat/config';

export function imageData(bytes: Uint8Array): string {
  let binary = '';
  for (let offset = 0; offset < bytes.length; offset += 32768) binary += String.fromCharCode(...bytes.subarray(offset, offset + 32768));
  return btoa(binary);
}

/**
 * What a chat upload may do. `inlineImages` also sends a png, jpeg, gif or webp as a native image in the message (off by default: the
 * file is saved and the message carries only its `@path`, which the agent reads with a tool, so no base64 rides along in every later
 * turn). `maxBytes` refuses a larger file before it is read or uploaded, with `tooLarge` as the reason shown beside the other failures.
 * `accept` is the picker's MIME/extension list: a file of another type is refused too (a drop or a paste does not pass the picker).
 */
export interface AttachmentPolicy { readonly inlineImages?: boolean | undefined; readonly maxBytes?: number | undefined; readonly tooLarge?: string | undefined; readonly accept?: string | undefined }

/** Whether a file passes a picker's `accept` list: `image/*`, an exact MIME type or an extension such as `.pdf`. An empty list accepts any file. */
export function acceptsFile(file: { readonly name: string; readonly type: string }, accept: string): boolean {
  const name = file.name.toLowerCase(), type = file.type.toLowerCase();
  const tokens = accept.split(',').map(token => token.trim().toLowerCase()).filter(Boolean);
  return tokens.length === 0 || tokens.some(token => token.startsWith('.') ? name.endsWith(token) : token.endsWith('/*') ? type.startsWith(token.slice(0, -1)) : type === token);
}

/**
 * Where a chat attachment is saved: its name with a short random suffix, so a second `image.png` (every pasted screenshot has that
 * name) or the same file attached again is a new file beside the first instead of a refused overwrite. The name has no whitespace,
 * because a chat mention ends at a space: each run of whitespace becomes `_`.
 */
export function attachmentPath(name: string): string {
  return uploadPath(name, randomUUID().slice(0, 8));
}

/** Successful files remain attached when another file is refused; every outcome remains visible in the shared file tree. */
export async function uploadRevisionAttachments(controller: FileTreeController, files: readonly File[], signal: AbortSignal, onPreparationFailure?: (name: string, reason: string) => void, policy: AttachmentPolicy = {}): Promise<readonly UploadResult[]> {
  const uploaded: UploadResult[] = [];
  let reason = 'No files were saved. Open Files to review the uploads.';
  for (const file of files) {
    if (signal.aborted) break;
    if (policy.maxBytes !== undefined && file.size > policy.maxBytes) { reason = policy.tooLarge ?? 'The file is too large to attach.'; onPreparationFailure?.(file.name, reason); continue; }
    if (policy.accept && !acceptsFile(file, policy.accept)) { reason = 'This file type is not accepted.'; onPreparationFailure?.(file.name, reason); continue; }
    try {
      const path = attachmentPath(file.name), bytes = new Uint8Array(await file.arrayBuffer());
      const upload = await controller.upload({ path, bytes, mediaType: file.type || 'application/octet-stream', signal });
      if (upload.state.kind === 'settled' && upload.state.result.kind === 'committed') {
        uploaded.push({ path, name: file.name, ...(policy.inlineImages && /^image\/(png|jpeg|gif|webp)$/.test(file.type) ? { image: { data: imageData(bytes), mimeType: file.type } } : {}) });
      } else if (upload.state.kind === 'settled' && 'reason' in upload.state.result) reason = upload.state.result.reason;
    } catch (error) { reason = error instanceof Error ? error.message : 'Upload failed'; onPreparationFailure?.(file.name, reason); }
  }
  if (!uploaded.length) throw new Error(reason);
  return uploaded;
}

'use client';

import { useEffect, useMemo, useRef, useState } from 'react';
import type { RevisionProvider } from '@hachej/boring-files/revision';
import { createFileTreeController } from '@hachej/boring-ui-kit/file-tree';
import type { FileTreeController } from '@hachej/boring-ui-kit/file-tree';
import type { AttachmentsConfig } from '../pi-chat/config';
import { uploadRevisionAttachments } from './revision-files';

export interface RevisionAttachmentsOptions {
  /** The workspace the files are saved in, under `uploads/`. Absent: no attachments. */
  readonly revisionProvider?: RevisionProvider | undefined;
  /**
   * The tree controller to save through. `AgentWorkspace` passes its Library's, so the page keeps one per workspace. Absent: the hook makes
   * one from `revisionProvider` and disposes it with the binding.
   */
  readonly fileTree?: FileTreeController | undefined;
  /** The picker's MIME/extension list (`image/*,.pdf`). Other types are refused. Any file when omitted. */
  readonly accept?: string | undefined;
  /** The host's size limit in bytes: a larger file is refused before it is read, with `tooLarge` as its reason. No limit when omitted. */
  readonly maxBytes?: number | undefined;
  readonly tooLarge?: string | undefined;
  /** Send a png, jpeg, gif or webp as a native image in the message too (off by default: the message carries only the `@path`). */
  readonly inlineImages?: boolean | undefined;
  /** A file that could not be saved, with its reason. Partial failures are reported here; an upload that saves nothing rejects with the reason. */
  readonly onPreparationFailure?: ((name: string, reason: string) => void) | undefined;
}

/**
 * The `attachments` config `PiChat` takes, saved through a revision provider: each file is written under `uploads/` with a short random suffix
 * (`uploadRevisionAttachments`), refused when it is over `maxBytes` or not in `accept`. Works for a bare `PiChat` as well as `AgentWorkspace`,
 * which passes its own `fileTree`. Returns `undefined` until there is a tree to save through.
 */
export function useRevisionAttachments({ revisionProvider, fileTree, accept, maxBytes, tooLarge, inlineImages = false, onPreparationFailure }: RevisionAttachmentsOptions): AttachmentsConfig | undefined {
  const [binding, setBinding] = useState<{ readonly provider: RevisionProvider; readonly tree: FileTreeController }>();
  useEffect(() => {
    if (fileTree || !revisionProvider) return;
    const tree = createFileTreeController({ revisionProvider });
    setBinding({ provider: revisionProvider, tree });
    return () => tree.dispose();
  }, [fileTree, revisionProvider]);
  const tree = fileTree ?? (binding?.provider === revisionProvider ? binding?.tree : undefined);
  // The failure callback is read when an upload starts, so a new callback does not rebuild the config, and a late failure of an upload
  // reports to the workspace it was started in (not the one selected since).
  const failure = useRef(onPreparationFailure); failure.current = onPreparationFailure;
  return useMemo<AttachmentsConfig | undefined>(() => tree ? {
    ...(accept !== undefined ? { accept } : {}),
    upload: (files: File[], signal: AbortSignal) => {
      const report = failure.current;
      return uploadRevisionAttachments(tree, files, signal, (name, reason) => report?.(name, reason),
        { inlineImages, ...(maxBytes !== undefined ? { maxBytes, tooLarge } : {}), ...(accept ? { accept } : {}) });
    },
  } : undefined, [tree, accept, inlineImages, maxBytes, tooLarge]);
}

'use client';

// What a kind is to the artifact panel and the file viewer (D-257): an app's `ArtifactKind`, or a document kind (Markdown and HTML edited
// over a revisioned controller; image and PDF read as bytes). These are contracts only: the kinds themselves come from the host, through
// `AgentWorkspace`'s `artifactKinds` or `ViewerOptions.kinds`. The pi-app-kinds item exports the default list (`defaultKinds`), whose
// kinds (the viewer items' `markdownKind`, `imageKind`...) satisfy these types structurally; none of the viewers is in this item.
import { lazy, useEffect } from 'react';
import type { ComponentType, ReactNode } from 'react';
import { LoaderCircleIcon } from 'lucide-react';
import type { MarkdownController } from '@hachej/boring-ui-kit/markdown';
import type { HtmlController } from '@hachej/boring-ui-kit/html';
import type { MarkdownEditorProps } from '@hachej/boring-ui-kit/markdown-editor';
import type { ArtifactKind, ArtifactKindViewProps } from '../pi-artifacts/artifact';
import type { ViewerShare } from '../viewer-frame/viewer-frame';
import type { InteractiveHtml } from '../viewer-frame/interactive-html';
import type { MediaSource } from '../viewer-frame/media';

/** The viewer bar's props the panel and the file viewer give every pane a document or media kind loads. */
export interface PaneBarProps {
  readonly title?: string;
  readonly subtitle?: ReactNode;
  readonly target?: unknown;
  readonly revision?: string;
  readonly headerStart?: ReactNode;
  readonly controls?: ReactNode;
  readonly onRefresh?: () => unknown;
  readonly onShare?: ViewerShare;
  readonly onClose?: () => unknown;
  readonly testId?: string;
  readonly titleTestId?: string;
}

/** What a Markdown kind's pane receives (the viewer-markdown item's `MarkdownPane` takes these and more). */
export interface MarkdownPaneInput extends PaneBarProps {
  readonly controller: MarkdownController;
  readonly initialMode?: 'rich' | 'source';
  readonly onModeChange?: (mode: 'rich' | 'source') => void;
  readonly formattingToolbar?: MarkdownEditorProps['formattingToolbar'];
  readonly onFormattingToolbarChange?: (toolbar: 'selection' | 'pinned') => void;
  readonly onAutosaveChange?: MarkdownEditorProps['onAutosaveChange'];
  readonly onBeforeLeaveChange?: MarkdownEditorProps['onAutosaveChange'];
}

/** What an HTML kind's pane receives (the viewer-html item's `HtmlPane`). */
export interface HtmlPaneInput extends PaneBarProps {
  readonly controller: HtmlController;
  readonly initialMode?: 'preview' | 'source';
  readonly onModeChange?: (mode: 'preview' | 'source') => void;
  readonly interactive?: InteractiveHtml;
}

/** What an image kind's pane receives (the viewer-image item's `ImagePane`): the bytes, a blob or the host's URL of a large file. */
export interface ImagePaneInput extends PaneBarProps, MediaSource { readonly name: string; readonly mediaType: string }

/** What a PDF kind's pane receives (the viewer-pdf item's `PdfPane`). */
export interface PdfPaneInput extends PaneBarProps, MediaSource { readonly name: string }

/** What a code kind's view receives (the viewer-code item's SVG and CSV views): of the panel's kind props, these. */
export interface CodeViewInput {
  readonly text: string;
  readonly artifact: { readonly title: string };
  readonly setControls?: ((controls: ReactNode) => void) | undefined;
}

type KindHead = Pick<ArtifactKind, 'match' | 'label' | 'icon' | 'fallback'>;
type Loads<Props> = { readonly load: () => Promise<{ readonly default: ComponentType<Props> }> };

/** A kind drawn by a view of the panel's text that reads fewer props than an `ArtifactKind` view (SVG, CSV). */
export type CodeKind = KindHead & Loads<CodeViewInput>;
/** A document kind edited over a revisioned controller (Markdown, HTML): the panel and the file viewer create the controller. */
export type EditorKind = KindHead & ((Loads<MarkdownPaneInput> & { readonly editor: 'markdown' }) | (Loads<HtmlPaneInput> & { readonly editor: 'html' }));
/** A kind that reads a file's bytes rather than its text (image, PDF): the file viewer draws it. */
export type MediaKind = KindHead & ((Loads<ImagePaneInput> & { readonly media: 'image' }) | (Loads<PdfPaneInput> & { readonly media: 'pdf' }));
/** Any kind the panel and the file viewer take: an app's `ArtifactKind`, a code kind, an editor kind or a media kind. */
export type PanelKind = ArtifactKind | CodeKind | EditorKind | MediaKind;

/** What the panel and the file viewer resolve through when the host passes no kinds: none, so every file shows as text. */
export const noKinds: readonly PanelKind[] = [];

export const isEditorKind = (kind: PanelKind | undefined): kind is EditorKind => !!kind && 'editor' in kind;
export const isMediaKind = (kind: PanelKind | undefined): kind is MediaKind => !!kind && 'media' in kind;

/** A kind that draws an artifact's text in the panel: an editor kind, or one with a renderer or a lazily loaded view (not image or PDF). */
export const drawsText = (kind: PanelKind): boolean => !isMediaKind(kind) && (isEditorKind(kind) || ('renderer' in kind && !!kind.renderer) || !!kind.load);

// One lazy component per loader, for the life of the page: a kind recreated on each render (a fresh comments object) keeps its loader
// identity when it is a module constant, and a loader seen again never re-suspends.
const views = new WeakMap<object, unknown>();

/** The `React.lazy` component of a kind's `load`, created once per loader. */
export function lazyView<Props>(load: () => Promise<{ readonly default: ComponentType<Props> }>): ComponentType<Props> {
  let view = views.get(load) as ComponentType<Props> | undefined;
  if (!view) { view = lazy(load) as unknown as ComponentType<Props>; views.set(load, view); }
  return view;
}

const renderers = new WeakMap<object, (props: ArtifactKindViewProps) => ReactNode>();

/** A kind's `load` as a renderer (one per loader): the panel draws it like a kind's own `renderer`, inside its `Suspense`. */
// A view takes the panel's props or fewer of them (the code views read only `text`, `artifact` and `setControls`).
export function lazyRenderer(load: () => Promise<{ readonly default: unknown }>): (props: ArtifactKindViewProps) => ReactNode {
  let render = renderers.get(load);
  if (!render) { const View = lazyView(load as () => Promise<{ readonly default: ComponentType<ArtifactKindViewProps> }>); render = props => <View {...props} />; renderers.set(load, render); }
  return render;
}

/** The spinner a viewer bar shows while its view loads. */
export function ViewLoading({ label }: { readonly label: string }) {
  return <p data-testid="viewer-loading" role="status" aria-label={label} className="m-0 flex flex-1 items-center justify-center p-6 text-muted-foreground">
    <LoaderCircleIcon className="size-5 animate-spin" aria-hidden="true" />
  </p>;
}

/** Calls `onMount(value)` once it commits: inside a `Suspense`, that is only after the lazy view beside it has loaded and mounted. */
export function Mounted({ value, onMount }: { readonly value: string; readonly onMount: (value: string) => void }) {
  useEffect(() => { onMount(value); }, [value, onMount]);
  return null;
}
